// Verificación de suscripción del webhook (GET de Meta).
// Meta envía hub.mode=subscribe, hub.verify_token y hub.challenge.
// Solo devolvemos el challenge si el token coincide con WHATSAPP_VERIFY_TOKEN.
const q = $input.first().json.query || {};
const expected = String($env.WHATSAPP_VERIFY_TOKEN || '');
const ok = expected.length > 0
  && q['hub.mode'] === 'subscribe'
  && String(q['hub.verify_token'] || '') === expected;
return [{ json: { ok, challenge: ok ? String(q['hub.challenge'] || '') : '' } }];

// Valida la cabecera X-Hub-Signature-256 que firma Meta:
// HMAC-SHA256 del cuerpo CRUDO usando el App Secret de la app de Meta.
// Requiere la opción "Raw Body" del Webhook y NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');

const appSecret = String($env.WHATSAPP_APP_SECRET || '');
const item = $input.first();
const headers = item.json.headers || {};
const signature = String(headers['x-hub-signature-256'] || '');

if (!appSecret) {
  return [{ json: { valid: false, reason: 'WHATSAPP_APP_SECRET no configurado' } }];
}
if (!item.binary || !item.binary.data) {
  return [{ json: { valid: false, reason: 'Sin cuerpo crudo: activar "Raw Body" en el Webhook' } }];
}

const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = 'sha256=' + crypto.createHmac('sha256', appSecret).update(raw).digest('hex');
const a = Buffer.from(signature);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return [{ json: { valid: false, reason: 'Firma ausente o inválida' } }];
}

let body;
try {
  body = JSON.parse(raw.toString('utf8'));
} catch (e) {
  return [{ json: { valid: false, reason: 'JSON inválido' } }];
}
return [{ json: { valid: true, body } }];

// Extrae los mensajes entrantes del payload de Meta y prepara la respuesta de prueba.
// - Ignora eventos de estado (sent/delivered/read): no son mensajes del alumno.
// - Ignora otros números de la misma cuenta (WHATSAPP_PHONE_NUMBER_ID).
// - Idempotencia: descarta message.id ya procesados (Meta reintenta entregas).
// - Lista blanca de prueba: solo responde a WA_TEST_ALLOWED_NUMBERS.
const phoneNumberId = String($env.WHATSAPP_PHONE_NUMBER_ID || '');
const allowed = String($env.WA_TEST_ALLOWED_NUMBERS || '')
  .split(',')
  .map((n) => n.replace(/\D/g, ''))
  .filter(Boolean);

const body = $input.first().json.body || {};
if (!phoneNumberId || body.object !== 'whatsapp_business_account') {
  return [];
}

// Los datos estáticos solo persisten en ejecuciones de producción (flujo activo),
// no en "Execute workflow" manual.
const staticData = $getWorkflowStaticData('global');
const seen = Array.isArray(staticData.seenMessageIds) ? staticData.seenMessageIds : [];

const out = [];
for (const entry of body.entry || []) {
  for (const change of entry.changes || []) {
    if (change.field !== 'messages') continue;
    const value = change.value || {};
    if (!value.metadata || value.metadata.phone_number_id !== phoneNumberId) continue;

    const names = {};
    for (const c of value.contacts || []) {
      names[c.wa_id] = (c.profile && c.profile.name) || '';
    }

    for (const m of value.messages || []) {
      if (!m.id || seen.includes(m.id)) continue;
      seen.push(m.id);

      const from = String(m.from || '').replace(/\D/g, '');
      if (!allowed.includes(from)) continue;

      const text = m.type === 'text' && m.text ? String(m.text.body || '') : null;
      const reply = text !== null
        ? `Recibido: "${text.slice(0, 300)}"\n\nPrueba de conexión WhatsApp - n8n OK.`
        : `Recibí un mensaje de tipo "${m.type}". En esta etapa de prueba solo respondo mensajes de texto.`;

      out.push({
        json: {
          message_id: m.id,
          from,
          name: names[m.from] || '',
          type: m.type,
          text,
          timestamp: m.timestamp,
          phone_number_id: value.metadata.phone_number_id,
          reply,
        },
      });
    }
  }
}

staticData.seenMessageIds = seen.slice(-1000);
return out;
